public static bool HasPathSum(BinNode<int> bt, int Sum)
{
    if (bt == null)
        return false;
    if (!bt.HasLeft() && !bt.HasRight())
        return bt.GetValue() == Sum;
    int Rest = Sum - bt.GetValue();
    return HasPathSum(bt.GetLeft(), Rest) || HasPathSum(bt.GetRight(), Rest);
}

